#!/bin/sh
# Builds static/vendor/pdfjs.js and static/vendor/pdfworker.js with
# Bun, then prepends the license notice of pdfjs-dist. The worker loads as a
# module worker. Neither file fetches cmaps, fonts or wasm at run time, because
# the viewer passes no such URLs to getDocument.
set -eu
cd "$(dirname "$0")"

main=../../static/vendor/pdfjs.js
worker=../../static/vendor/pdfworker.js
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

bun install --frozen-lockfile
bun build entry.js --minify --format=esm --target=browser --outfile "$tmp/main.js"
bun build worker.js --minify --format=esm --target=browser --outfile "$tmp/worker.js"

dir=node_modules/pdfjs-dist
version=$(sed -n 's/^ *"version": *"\([^"]*\)".*/\1/p' "$dir/package.json" | head -n 1)
{
  echo "/*!"
  echo " * Markspace vendored pdf.js bundle, generated by internal/web/vendor/pdfjs/build.sh."
  echo " * Do not edit by hand."
  echo " * pdfjs-dist $version (Apache-2.0) Copyright Mozilla Foundation"
  echo " *"
  sed -e 's/\*\//* \//g' -e '/./,$!d' -e 's/^/ * /' -e 's/ *$//' "$dir/LICENSE"
  echo " */"
} > "$tmp/banner"

cat "$tmp/banner" "$tmp/main.js" > "$main"
cat "$tmp/banner" "$tmp/worker.js" > "$worker"
msize=$(wc -c < "$main")
wsize=$(wc -c < "$worker")
echo "wrote $main ($msize bytes)"
echo "wrote $worker ($wsize bytes)"
if [ "$msize" -gt 700000 ] || [ "$wsize" -gt 1600000 ]; then
  echo "bundle exceeds the budget of 700 KB for the library or 1.6 MB for the worker" >&2
  exit 1
fi
